mapper.select:
SELECT 
FROM alarm_log


        AND INSTR(alarm_log.device_key, #{queryForm.deviceKey})


        AND alarm_log.level = #{queryForm.level}


        AND alarm_log.status = #{queryForm.status}


        AND alarm_log.trigger_time >= #{queryForm.triggerTimeBegin}


        AND alarm_log.trigger_time <= #{queryForm.triggerTimeEnd}



    ORDER BY alarm_log.id DESC
